'use strict';
let screenshots=[],activeScreenshot=0,ocrWorker=null,ocrBusy=false,ocrCancelled=false,ocrLoad=null;
function readCrop(){const shot=screenshots[activeScreenshot];if(!shot)return;shot.crop={left:+$('#cropLeft').value,right:+$('#cropRight').value,top:+$('#cropTop').value,bottom:+$('#cropBottom').value};updateCropOverlay()}
function updateCropOverlay(){const shot=screenshots[activeScreenshot],box=$('#cropOverlay');if(!shot||!box)return;const c=shot.crop;box.style.left=c.left+'%';box.style.top=c.top+'%';box.style.width=Math.max(0,c.right-c.left)+'%';box.style.height=Math.max(0,c.bottom-c.top)+'%'}
function showScreenshot(index){activeScreenshot=index;const shot=screenshots[index];$('#ocrPreviews').innerHTML=`<div class="screenshot-tabs">${screenshots.map((s,i)=>`<button data-shot="${i}" class="${i===index?'primary':''}">${i+1}. ${esc(s.file.name.slice(0,22))}</button>`).join('')}</div><div class="screenshot-frame"><img src="${shot.url}" alt="Participant screenshot ${index+1}"><div id="cropOverlay"></div></div>`;for(const [k,id]of [['left','cropLeft'],['right','cropRight'],['top','cropTop'],['bottom','cropBottom']])$('#'+id).value=shot.crop[k];$$('[data-shot]').forEach(b=>b.onclick=()=>{readCrop();showScreenshot(+b.dataset.shot)});$('#ocrCrop').classList.remove('hidden');updateCropOverlay()}
$('#ocrFiles').onchange=e=>{if(ocrBusy)return;const files=[...e.target.files];if(files.length>10){toast('Choose up to 10 screenshots at a time.');return}if(files.some(f=>f.size>20*1024*1024)){toast('Use screenshots under 20 MB each.');return}screenshots.forEach(s=>URL.revokeObjectURL(s.url));screenshots=files.map(file=>({file,url:URL.createObjectURL(file),crop:{left:0,right:100,top:0,bottom:100}}));$('#runOCR').disabled=!screenshots.length;if(screenshots.length){showScreenshot(0);$('#ocrStatus').textContent='Crop each screenshot to its names column, then choose Read screenshots.'}else{$('#ocrPreviews').innerHTML='';$('#ocrCrop').classList.add('hidden')}};
for(const id of ['cropLeft','cropRight','cropTop','cropBottom'])$('#'+id).oninput=readCrop;
function loadOCR(){if(window.Tesseract)return Promise.resolve();if(ocrLoad)return ocrLoad;ocrLoad=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='vendor/ocr/tesseract.min.js';script.onload=resolve;script.onerror=()=>{ocrLoad=null;reject(Error('The OCR engine could not load. Paste participant names instead or retry.'))};document.head.appendChild(script)});return ocrLoad}
async function croppedImage(shot){const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('This image could not be opened. Use PNG or JPEG screenshots.'));img.src=shot.url});const c=shot.crop;if(![c.left,c.right,c.top,c.bottom].every(Number.isFinite)||c.left<0||c.top<0||c.right>100||c.bottom>100||c.right<=c.left||c.bottom<=c.top)throw Error('Check crop edges: right must exceed left, and bottom must exceed top.');const sx=img.naturalWidth*c.left/100,sy=img.naturalHeight*c.top/100,sw=img.naturalWidth*(c.right-c.left)/100,sh=img.naturalHeight*(c.bottom-c.top)/100;const scale=Math.min(2.5,1600/sw,2600/sh);const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(sw*scale));canvas.height=Math.max(1,Math.round(sh*scale));const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(img,sx,sy,sw,sh,0,0,canvas.width,canvas.height);const image=ctx.getImageData(0,0,canvas.width,canvas.height),d=image.data;let sum=0;for(let i=0;i<d.length;i+=4){const gray=Math.round(.299*d[i]+.587*d[i+1]+.114*d[i+2]);sum+=gray;d[i]=d[i+1]=d[i+2]=gray}const invert=sum/(d.length/4)<115;if(invert)for(let i=0;i<d.length;i+=4)d[i]=d[i+1]=d[i+2]=255-d[i];ctx.putImageData(image,0,0);return canvas}
$('#cancelOCR').onclick=async()=>{ocrCancelled=true;$('#ocrStatus').textContent='Cancelling OCR…';if(ocrWorker){await ocrWorker.terminate();ocrWorker=null}};
$('#runOCR').onclick=async()=>{if(ocrBusy||!screenshots.length)return;readCrop();ocrBusy=true;ocrCancelled=false;$('#runOCR').disabled=true;$('#ocrFiles').disabled=true;$('#cancelOCR').classList.remove('hidden');let index=0;try{await loadOCR();if(ocrCancelled)return;$('#ocrStatus').textContent='Loading OCR language data on this device…';const absolute=path=>new URL(path,location.href).href;ocrWorker=await Tesseract.createWorker($('#ocrLanguage').value,1,{workerPath:absolute('vendor/ocr/worker.min.js'),corePath:absolute('vendor/ocr/core/'),langPath:absolute('vendor/ocr/lang'),workerBlobURL:false,logger:m=>{if(!ocrCancelled)$('#ocrStatus').textContent=`Screenshot ${index+1}/${screenshots.length}: ${m.status}${Number.isFinite(m.progress)?' '+Math.round(m.progress*100)+'%':''}`}});if(ocrCancelled)return;await ocrWorker.setParameters({tessedit_pageseg_mode:'6',preserve_interword_spaces:'1'});const texts=[];for(index=0;index<screenshots.length;index++){if(ocrCancelled)break;const canvas=await croppedImage(screenshots[index]);const result=await ocrWorker.recognize(canvas);canvas.width=canvas.height=1;if(result.data.text.trim())texts.push(result.data.text.trim())}if(!ocrCancelled){const existing=$('#attendeeText').value.trim();$('#attendeeText').value=[existing,...texts].filter(Boolean).join('\n');$('#ocrStatus').textContent=texts.length?'Text extracted. Correct the text and choose Review roster matches. Nothing has been saved as attendance.':'No text found. Try a tighter crop, choose the right language, or paste the names.';toast('OCR finished. Review the names before saving.')}}catch(e){$('#ocrStatus').textContent=ocrCancelled?'OCR cancelled. No attendance was saved.':'OCR failed: '+(e.message||'Try a smaller screenshot or paste names instead.')}finally{if(ocrWorker){try{await ocrWorker.terminate()}catch{}ocrWorker=null}if(ocrCancelled)$('#ocrStatus').textContent='OCR cancelled. No attendance was saved.';ocrBusy=false;$('#runOCR').disabled=!screenshots.length;$('#ocrFiles').disabled=false;$('#cancelOCR').classList.add('hidden')}};
